import logging
import telnetlib
import time
import socket
import sys


class TelnetClient(object):
    """Class to control telnet connection to JFW rf_attenuator"""

    def __init__(self):
        self.client = None
        self.host = None
        self.port = None
        logging.basicConfig(format="%(asctime)s %(levelname)s %(message)s", level=logging.DEBUG)

    def connect(self, host, port):
        """
        Establish telnet connection
        :param host: telnet host
        :param port: telnet port
        """
        logging.debug("fun_call: " + sys._getframe().f_code.co_name)
        self.host = host
        self.port = port
        self._establish_connection()

    def _establish_connection(self):
        logging.info('Establishing connection to rf_attenuator.')
        for ii in range(2):
            try:
                self.client = telnetlib.Telnet(self.host, int(self.port))
                logging.debug(self.client.read_very_eager())
                logging.info('Connection established.')
                break
            except socket.error as e:
                logging.info("Telnet trying to reconnect: " + str(ii))
                logging.info(str(e))
                time.sleep(5)
        else:
            raise Exception("Error in rf_attenuator connection")

    def write_command(self, command):
        """
        Write telnet command
        :param command
        """
        try:
            logging.debug('Sending command to client: {}'.format(command))
            self._write(command)
        except Exception as e:
            try:
                logging.debug("Exception during sending command: {}".format(str(e)))
                logging.debug('Trying to reconnect ...')
                self._establish_connection()
                self._write(command)
            except Exception as e:
                logging.debug("Exception during resending command: {}".format(str(e)))
                logging.exception(str(e))
                raise

    def read(self):
        return self.client.read_very_eager()

    def read_command_output(self, command, read_method='eager', read_flag='\r\n'):
        """
        Write telnet command and get response. Retry if necessary.

        :param command:
        :param read_method:
        :param read_flag:
        """
        try:
            logging.debug('Sending command to client: {}'.format(command))
            return self.write_and_read(command, read_method, read_flag)
        except Exception as e:
            try:
                logging.debug("Exception during sending command: {}".format(str(e)))
                self._establish_connection()
                return self.write_and_read(command, read_method, read_flag)
            except Exception as e:
                logging.exception("General error in send command")
                logging.exception(str(e))
                raise

    def _write(self, command):
        """
        Write a telnet command
        :param command: command to be written
        """
        command += '\r\n'
        self.client.write(command.encode('utf-8'))
        time.sleep(0.05)

    def write_and_read(self, command, read_method, read_flag, timeout=2):
        """
        Write telnet command and read the response.

        This method sends a command to the telnet client and reads the response.
        It handles invalid bytes in the response by skipping them during
        decoding.

        :param command: Command to be sent to the client.
        :param read_method: Method to read the response ('eager' or 'until').
        :param read_flag: Flag to read the response (used with 'until' method).
        :param timeout: Timeout for the response (used with 'until' method).
        :return: Client's response as a decoded string.
        """
        self.client.read_very_eager()
        self._write(command)
        if read_method == 'eager':
            raw_output = self.client.read_very_eager()
        elif read_method == 'until':
            raw_output = self.client.read_until(read_flag.encode('utf-8'), int(timeout))
        else:
            return ""
        return raw_output.decode('utf-8', errors='ignore')

    def close_connection(self):
        """Close telnet connection"""
        try:
            if self.client is not None:
                self.client.close()
                self.client = None
        except OSError as e:
            logging.exception("OSError in client.close(): {}".format(e))

    def __del__(self):
        self.close_connection()
